namespace TutorFlow.Domain.Authorization;

/// <summary>Rol declarado y validado en L1 (SPEC 6.2).</summary>
public enum RolAcademico
{
    Estudiante,
    Coordinador,
}

/// <summary>
/// Principal inmutable construido por L1 (consistencia de identidad, no autenticacion; SPEC 6.5).
/// Su alcance es el id propio o los programas del coordinador. Nunca se deriva de la pregunta ni del LLM.
/// Refinado en T-02.
/// </summary>
public sealed record PrincipalAcademico
{
    public PrincipalAcademico(RolAcademico rol, string id, IEnumerable<string>? programasCoordinados = null)
    {
        ArgumentException.ThrowIfNullOrEmpty(id);
        Rol = rol;
        Id = id;
        ProgramasCoordinados = (programasCoordinados ?? Array.Empty<string>()).ToArray();
    }

    public RolAcademico Rol { get; }

    public string Id { get; }

    /// <summary>Programas coordinados (vacio para un estudiante).</summary>
    public IReadOnlyList<string> ProgramasCoordinados { get; }
}

namespace TutorFlow.Domain.Authorization;

public enum TipoRecurso
{
    Reglamento,
    DatosEstudiante,
    ProgramaEstudiantes,
    DatosCoordinador,
}

/// <summary>
/// Recurso a autorizar. <see cref="ProgramaId"/> es el programa del estudiante objetivo (resuelto desde el roster)
/// o el programa listado; nunca se toma de la pregunta ni del LLM. Un objetivo ausente del roster se deniega.
/// </summary>
public sealed record RecursoAcademico(TipoRecurso Tipo, string? Id = null, string? ProgramaId = null);

public sealed record DecisionAutorizacion(bool Permitido, string Motivo)
{
    public static DecisionAutorizacion Permitir() => new(true, "permitido");

    public static DecisionAutorizacion Denegar(string motivo) => new(false, motivo);
}

/// <summary>
/// Politica pura y determinista (SPEC 6.1). Solo depende del principal y del recurso; el LLM ni concede ni deniega.
/// </summary>
public interface IAuthorizationPolicy
{
    DecisionAutorizacion Authorize(PrincipalAcademico principal, RecursoAcademico recurso);
}

